-- Switchyard schema v1.
--
-- Conventions
--   * Primary keys are UUIDv7 strings (time ordered) generated by Core.
--   * Timestamps are INTEGER Unix epoch milliseconds (UTC).
--   * Structured payloads are JSON TEXT validated with json_valid().
--   * Enumerations are TEXT constrained by CHECK.
--
-- Only `projects` and `events` are written by the first milestone. The other
-- tables establish the relational model that agent sessions, tasks, reviews
-- and approvals will populate; they carry no speculative behaviour.

-- A registered local Git repository. Removing a registration never touches
-- files on disk.
CREATE TABLE projects (
    id            TEXT    PRIMARY KEY NOT NULL,
    name          TEXT    NOT NULL CHECK (length(name) > 0),
    root_path     TEXT    NOT NULL UNIQUE,
    created_at    INTEGER NOT NULL,
    updated_at    INTEGER NOT NULL
) STRICT;

-- An isolated working directory for a project: the primary checkout or a
-- dedicated Git worktree for an agent.
CREATE TABLE workspaces (
    id            TEXT    PRIMARY KEY NOT NULL,
    project_id    TEXT    NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    kind          TEXT    NOT NULL CHECK (kind IN ('primary', 'worktree')),
    path          TEXT    NOT NULL UNIQUE,
    branch        TEXT,
    base_ref      TEXT,
    status        TEXT    NOT NULL CHECK (status IN ('active', 'archived', 'missing')),
    created_at    INTEGER NOT NULL,
    updated_at    INTEGER NOT NULL
) STRICT;
CREATE INDEX workspaces_project ON workspaces (project_id);

-- A configured native coding agent (an installation of Claude Code or Codex
-- with a display name). Runtime instances are `sessions`.
CREATE TABLE agents (
    id            TEXT    PRIMARY KEY NOT NULL,
    vendor        TEXT    NOT NULL CHECK (vendor IN ('claude_code', 'codex')),
    display_name  TEXT    NOT NULL,
    executable    TEXT    NOT NULL,
    cli_version   TEXT,
    created_at    INTEGER NOT NULL,
    updated_at    INTEGER NOT NULL
) STRICT;

-- One running (or finished) agent process bound to a workspace.
CREATE TABLE sessions (
    id                 TEXT    PRIMARY KEY NOT NULL,
    project_id         TEXT    NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    workspace_id       TEXT    REFERENCES workspaces (id) ON DELETE SET NULL,
    agent_id           TEXT    NOT NULL REFERENCES agents (id),
    -- Identifier assigned by the vendor (Claude session id / Codex thread id),
    -- used for resumption.
    vendor_session_id  TEXT,
    status             TEXT    NOT NULL CHECK (status IN
                           ('starting', 'active', 'idle', 'completed', 'failed', 'terminated')),
    pid                INTEGER,
    started_at         INTEGER NOT NULL,
    ended_at           INTEGER,
    exit_code          INTEGER
) STRICT;
CREATE INDEX sessions_project ON sessions (project_id);
CREATE INDEX sessions_status ON sessions (status);

CREATE TABLE tasks (
    id                 TEXT    PRIMARY KEY NOT NULL,
    project_id         TEXT    NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    parent_task_id     TEXT    REFERENCES tasks (id) ON DELETE CASCADE,
    title              TEXT    NOT NULL,
    description        TEXT,
    status             TEXT    NOT NULL CHECK (status IN
                           ('open', 'assigned', 'in_progress', 'in_review', 'blocked', 'done', 'cancelled')),
    assigned_agent_id  TEXT    REFERENCES agents (id) ON DELETE SET NULL,
    -- NULL when created by the human operator.
    created_by_agent_id TEXT   REFERENCES agents (id) ON DELETE SET NULL,
    created_at         INTEGER NOT NULL,
    updated_at         INTEGER NOT NULL
) STRICT;
CREATE INDEX tasks_project ON tasks (project_id, status);

-- Structured messages exchanged between agents and/or the operator.
CREATE TABLE messages (
    id                 TEXT    PRIMARY KEY NOT NULL,
    project_id         TEXT    NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    task_id            TEXT    REFERENCES tasks (id) ON DELETE SET NULL,
    in_reply_to        TEXT    REFERENCES messages (id) ON DELETE SET NULL,
    -- NULL sender/recipient means the human operator.
    from_agent_id      TEXT    REFERENCES agents (id) ON DELETE SET NULL,
    to_agent_id        TEXT    REFERENCES agents (id) ON DELETE SET NULL,
    kind               TEXT    NOT NULL,
    body               TEXT    NOT NULL CHECK (json_valid(body)),
    created_at         INTEGER NOT NULL
) STRICT;
CREATE INDEX messages_project ON messages (project_id, created_at);

-- Review findings raised against a task or session.
CREATE TABLE findings (
    id                 TEXT    PRIMARY KEY NOT NULL,
    project_id         TEXT    NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    task_id            TEXT    REFERENCES tasks (id) ON DELETE SET NULL,
    session_id         TEXT    REFERENCES sessions (id) ON DELETE SET NULL,
    reported_by_agent_id TEXT  REFERENCES agents (id) ON DELETE SET NULL,
    severity           TEXT    NOT NULL CHECK (severity IN ('info', 'low', 'medium', 'high', 'critical')),
    status             TEXT    NOT NULL CHECK (status IN ('open', 'acknowledged', 'resolved', 'dismissed')),
    title              TEXT    NOT NULL,
    detail             TEXT,
    file_path          TEXT,
    line_start         INTEGER,
    line_end           INTEGER,
    created_at         INTEGER NOT NULL,
    resolved_at        INTEGER
) STRICT;
CREATE INDEX findings_project ON findings (project_id, status);

-- Requests from an agent that require an operator (or policy) decision.
CREATE TABLE approvals (
    id                 TEXT    PRIMARY KEY NOT NULL,
    project_id         TEXT    NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    session_id         TEXT    REFERENCES sessions (id) ON DELETE SET NULL,
    task_id            TEXT    REFERENCES tasks (id) ON DELETE SET NULL,
    kind               TEXT    NOT NULL,
    request            TEXT    NOT NULL CHECK (json_valid(request)),
    status             TEXT    NOT NULL CHECK (status IN
                           ('pending', 'approved', 'denied', 'expired', 'cancelled')),
    decided_by         TEXT,
    decision_note      TEXT,
    created_at         INTEGER NOT NULL,
    decided_at         INTEGER
) STRICT;
CREATE INDEX approvals_pending ON approvals (status, created_at);

-- Centrally managed permission rules. NULL project/agent means "all".
CREATE TABLE permissions (
    id                 TEXT    PRIMARY KEY NOT NULL,
    project_id         TEXT    REFERENCES projects (id) ON DELETE CASCADE,
    agent_id           TEXT    REFERENCES agents (id) ON DELETE CASCADE,
    rule               TEXT    NOT NULL,
    effect             TEXT    NOT NULL CHECK (effect IN ('allow', 'ask', 'deny')),
    created_at         INTEGER NOT NULL
) STRICT;
CREATE INDEX permissions_scope ON permissions (project_id, agent_id);

-- Recorded technical decisions (by the operator or agents) and their rationale.
CREATE TABLE decisions (
    id                 TEXT    PRIMARY KEY NOT NULL,
    project_id         TEXT    NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    task_id            TEXT    REFERENCES tasks (id) ON DELETE SET NULL,
    title              TEXT    NOT NULL,
    context            TEXT,
    decision           TEXT    NOT NULL,
    rationale          TEXT,
    decided_by_agent_id TEXT   REFERENCES agents (id) ON DELETE SET NULL,
    created_at         INTEGER NOT NULL
) STRICT;
CREATE INDEX decisions_project ON decisions (project_id, created_at);

-- Durable, append-only event journal.
--
-- `seq` is the total order of the journal. Correlation columns intentionally
-- have no foreign keys: the journal is an immutable history and must outlive
-- the entities it mentions (e.g. a removed project).
CREATE TABLE events (
    seq             INTEGER PRIMARY KEY AUTOINCREMENT,
    id              TEXT    NOT NULL UNIQUE,
    schema_version  INTEGER NOT NULL,
    event_type      TEXT    NOT NULL,
    occurred_at     INTEGER NOT NULL,
    project_id      TEXT,
    workspace_id    TEXT,
    session_id      TEXT,
    task_id         TEXT,
    agent_id        TEXT,
    causation_id    TEXT,
    payload         TEXT    NOT NULL CHECK (json_valid(payload))
) STRICT;
CREATE INDEX events_project ON events (project_id, seq);
CREATE INDEX events_type ON events (event_type, seq);

CREATE TRIGGER events_no_update BEFORE UPDATE ON events
BEGIN
    SELECT RAISE(ABORT, 'events are append-only');
END;

CREATE TRIGGER events_no_delete BEFORE DELETE ON events
BEGIN
    SELECT RAISE(ABORT, 'events are append-only');
END;
